package com.sathavahana.kalamkari.dto; import com.sathavahana.kalamkari.domain.*; import java.math.*; import java.util.*; public record OrderDto(Long id,String status,String paymentStatus,BigDecimal totalAmount,List<Item> items){public record Item(Long productId,String name,int quantity,BigDecimal unitPrice){} public static OrderDto of(Order o){return new OrderDto(o.getId(),o.getStatus().name(),"PENDING",o.getTotalAmount(),o.getItems().stream().map(x->new Item(x.getProduct().getId(),x.getProduct().getName(),x.getQuantity(),x.getUnitPrice())).toList());}}
